        span[data-testid="add-widget-modal"] {
          [data-testid^="widget"] {
            background-color: @surface0;
            border-color: @surface1;

            span {
              color: @text;
            }
            div:has(> button) {
              border-color: @surface1;
            }
            button {
              .neutral-button(@surface1, @surface2);
            }
          }
        }
      }
      span[data-testid="loading-overlay"] > span {
        background-color: fade(@base, 40%);
      }
