    #content > div > div[data-widget-dashboard-dark-root] > div {
      background-color: @base;

      button[data-testid^="add-widget-placeholder"],
      button[data-testid="customize-dashboard-button"] {
        .accent-button-hollow();
      }

      button[data-testid="cancel-customize-button"] {
        .neutral-button();
      }

      button[data-testid="save-customize-button"] {
        .accent-button();
      }

      svg {
        color: @text;
      }

      #dashboard section {
        background-color: @surface0;

        [data-cid*="BaseButton"]:not([data-testid*="hide"]):not(
          [data-testid^="color-picker"]
        ) {
          .neutral-button();
          &[aria-current="page"] {
            color: black;
            .accent-button();
          }
        }

        span[title] {
          color: @text;
        }

        [style="all: unset;"] {
          color: @text !important;
        }

        &[data-testid="widget-course-work-combined-widget"] {
          [data-testid^="statistics-card"] {
            background-color: @surface1;
          }
          [data-testid="statistics-card-Due"] span {
            color: @blue !important;
          }
          [data-testid="statistics-card-Missing"] span {
            color: @red !important;
          }
          [data-testid="statistics-card-Submitted"] span {
            color: @green !important;
          }
          /* individual assignment cards */
          li > [data-testid^="listed-course-work-item"] > div {
            background-color: @surface1;
            div:has(> span > svg) {
              background-color: fade(@blue, 40%);
            }
            a > span {
              color: @blue !important;
            }

            span[data-testid^="due_soon-status-pill"] {
              background-color: fade(@blue, 40%);
              > span {
                background-color: transparent;
              }
            }
            span[data-testid^="submitted-status-pill"] {
              background-color: fade(@green, 40%);
              > span {
                background-color: transparent;
              }
            }
            /* not sure if this is the right id because i don't have missing work... */
            span[data-testid^="missing-status-pill"] {
              background-color: fade(@red, 40%);
              > span {
                background-color: transparent;
              }
            }
          }
        }

        &[data-testid^="widget-todo_list"] {
          div:has(> span[data-cid="Select SimpleSelect"]) {
            border-color: @surface2;
          }
          li > div {
            background-color: @surface1;
            border-color: @surface2;
          }
        }

        &[data-testid^="widget-inbox-widget"] {
          label span[class$="formFieldLayout__label"] {
            color: @text;
          }
          li > div {
            border-color: @surface1;
          }
        }

        &[data-testid^="widget-progress_overview"] {
          color: @text;
          > span > div > div {
            &:first-child {
              /* legend for child below */
              li {
                color: @text;
              }
            }
            &:last-child {
              /* contains course progress */
              [color="primary-inverse"] {
                color: @crust;
              }
              > div {
                /* data-testid="course-progress-item-xxxxxx" */
                ul li {
                  color: @text;
                  [class$="delimiter"] {
                    color: @surface2;
                  }
                }
                div[data-testid^="progress-segment-submitted"] {
                  background-color: @peach;
                }
                div[data-testid^="progress-segment-remaining"] {
                  background-color: @subtext1;
                }
                div[data-testid^="progress-segment-no-assignments"] {
                  background-color: @subtext1;
                }
              }
            }
          }
        }

        &[data-testid="widget-people-widget"] {
          ul[data-cid="List"] span {
            color: @text;
          }
        }

        &[data-testid="widget-course-grades-widget"] {
          span[data-testid$="name"] {
            color: @text;
          }
          div[data-testid^="course-grade"] {
            background-color: @surface1;
          }
        }

        &[data-testid="widget-announcements-widget"] {
          [data-testid^="announcement-item"] {
            border-color: @surface1;
          }
        }

        [color="primary-inverse"] {
          color: @text;
        }
      }
