    }

    /* STUDIO */
    #settings_page_wrapper,
    #collection_shared_content,
    #collection_user_content {
      background-color: @base;
      span[role="contentinfo"] {
        border-color: @surface1;
      }
    }
    .CollectionShow__mediaListWrapper {
      img {
        background-color: transparent;
      }
    }
    .DefaultLayout__main {
      color: @text;
    }
    h1 {
      color: @text;
    }
    #lti_media_picker {
      nav {
        background-color: @mantle;
        border-block-end-color: @surface0;
      }
      ul a[class$="Button"] div {
        color: @text;
      }
      li div[class$="topNavBarItem__container"]::after {
        background-color: @surface1;
      }
    }
    #media_upload_holder button img {
      filter: @text-filter;
    }
    span[class$="toggleDetails__summary"] > span {
      color: @text;
    }
    div[class$="toggleDetails__details"] {
      color: @text;
    }

    /* ASSIGNMENT CREATION */
    .page-action-list a {
      border-bottom-color: @surface1;
    }

    /* EXTENSIONS */
    /* BetterCampus */
    --bcsidebar-selection: @accent;
    --bcbackground-0-ungradient: @base;
    --bcbackground-0: @base;
    --bcbackground-1-ungradient: @surface0;
    --bcbackground-1: @surface0;
    --bcbackground-2-ungradient: @surface1;
    --bcbackground-2: @surface1;
    --bcborders-ungradient: @surface0;
    --bcborders: @surface0;
    --bclinks-ungradient: @blue;
    --bclinks: @blue;
    --bctext-0-ungradient: @text;
    --bctext-0: @text;
    --bctext-1-ungradient: @subtext0;
    --bctext-1: @subtext0;
    --bctext-2-ungradient: @subtext1;
    --bctext-2: @subtext1;
    --bccards-ungradient: @surface0;
    --bccards: @surface0;
    --bcshadow: 0 0 10px 0 transparent;
  }
}

